import{_ as a}from"./chunks/ilabs-ins-u.DpFWb_ew.js";import{_ as r,c as t,o,al as i}from"./chunks/framework.D8UyiDWg.js";const m=JSON.parse('{"title":"Inertial Labs INS (All sensors, including INS-U/INS-DU)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/sensor/inertiallabs.md","filePath":"uk/sensor/inertiallabs.md"}'),n={name:"uk/sensor/inertiallabs.md"};function s(l,e,c,d,h,u){return o(),t("div",null,e[0]||(e[0]=[i('<h1 id="inertial-labs-ins-all-sensors-including-ins-u-ins-du" tabindex="-1">Inertial Labs INS (All sensors, including INS-U/INS-DU) <a class="header-anchor" href="#inertial-labs-ins-all-sensors-including-ins-u-ins-du" aria-label="Permalink to &quot;Inertial Labs INS (All sensors, including INS-U/INS-DU)&quot;">​</a></h1><p>Inertial Labs designs and develops <a href="https://inertiallabs.com/products/imu-inertial-measurement-units/" target="_blank" rel="noreferrer">IMU</a>, <a href="https://inertiallabs.com/products/ahrs/" target="_blank" rel="noreferrer">AHRS</a>, <a href="https://inertiallabs.com/products/ins-inertial-navigation-systems/" target="_blank" rel="noreferrer">GNSS/INS</a> and <a href="https://inertiallabs.com/" target="_blank" rel="noreferrer">other</a> solutions. A universal protocol is used for <a href="https://inertiallabs.com/" target="_blank" rel="noreferrer">all Inertial Labs sensors</a>.</p><p><img src="'+a+'" alt="INS-U"></p><p>Benefits to PX4 users:</p><ul><li>Вища точність оцінки напрямку, крену та кочення</li><li>Більш надійна геоприв&#39;язка GNSS</li><li>Покращена точність позиціонування та установки під час конфлікту супутникового зв&#39;язку</li><li>Продуктивність при динамічних умовах (наприклад, запуски катапультою, операції VTOL, високі g або високі операції з великою кутовою швидкістю)</li><li>Work in different spoofing and jamming conditions</li></ul><p>PX4 can use these in a mode that provides only raw sensor output (the default), or as an <a href="./../sensor/inertial_navigation_systems.html">external INS</a> that provides both sensor output and INS data such as position and velocity estimates. The mode is configurable using a parameter.</p><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p><a href="https://inertiallabs.com/inertial-labs-inc/contact-inertial-labs-team/" target="_blank" rel="noreferrer">Get technical support or send requests to sales team</a>. Recommended sensors:</p><ul><li><a href="https://inertiallabs.com/ins-u-datasheet" target="_blank" rel="noreferrer">INS-U GNSS/INS</a>: Recommended for fixed-wing systems without hovering, where static heading is not necessary.</li><li><a href="https://inertiallabs.com/ins-du-datasheet" target="_blank" rel="noreferrer">INS-DU DUAL GNSS/INS</a>: Recommended for multicopter systems where hovering and low dynamics requires the use of static heading.</li></ul><h2 id="налаштування-програмного-забезпечення" tabindex="-1">Налаштування програмного забезпечення <a class="header-anchor" href="#налаштування-програмного-забезпечення" aria-label="Permalink to &quot;Налаштування програмного забезпечення&quot;">​</a></h2><h3 id="підключення" tabindex="-1">Підключення <a class="header-anchor" href="#підключення" aria-label="Permalink to &quot;Підключення&quot;">​</a></h3><p>Connect the sensor to any unused flight controller serial interface, such as a spare <code>GPS</code> or <code>TELEM</code>.</p><h3 id="встановлення" tabindex="-1">Встановлення <a class="header-anchor" href="#встановлення" aria-label="Permalink to &quot;Встановлення&quot;">​</a></h3><p>The Inertial Labs sensors can be mounted in any orientation. You can set offsets for coordinate axes in the sensor-configuration software that is provided with your sensor.</p><h2 id="конфігурація-прошивки" tabindex="-1">Конфігурація прошивки <a class="header-anchor" href="#конфігурація-прошивки" aria-label="Permalink to &quot;Конфігурація прошивки&quot;">​</a></h2><h3 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h3><p>To use the Inertial Labs driver:</p><ol><li><p>Build the firmware with the <a href="./../modules/modules_driver_ins.html#ilabs">ilabs</a> module.</p><p>The module is included by default for many boards. You can check by searching for the keys <code>CONFIG_COMMON_INS</code> (all INS drivers) and <code>CONFIG_DRIVERS_INS_ILABS</code> (ilabs driver) in the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v6c/default.px4board#L25" target="_blank" rel="noreferrer">default.px4board</a> configuration file for your target board.</p><p>If it is not present, you can add the key to your <code>default.px4board</code> file, or include it using the <a href="./../hardware/porting_guide_config.html#px4-board-configuration-kconfig">kconfig board configuration</a>: Drivers -&gt; INS -&gt; ilabs.</p></li><li><p><a href="./../advanced_config/parameters.html">Set the parameter</a> <a href="./../advanced_config/parameter_reference.html#SENS_ILABS_CFG">SENS_ILABS_CFG</a> to the hardware port connected to the sensor, such as a spare <code>GPS</code> or <code>TELEM</code>. Make sure that nothing else is configured to use the port (for more information see <a href="./../peripherals/serial_configuration.html">Serial Port Configuration</a>).</p></li><li><p>Перезавантажте PX4.</p></li><li><p>Налаштуйте водія як зовнішній INS або надайте сирові дані:</p><ul><li><p>For external INS, set <a href="./../advanced_config/parameter_reference.html#ILABS_MODE">ILABS_MODE</a> to <code>INS</code>.</p></li><li><p>For raw inertial sensors, set <a href="./../advanced_config/parameter_reference.html#ILABS_MODE">ILABS_MODE</a> to <code>Sensors Only</code>.</p><p>You can then prioritize inertial labs sensors using <a href="./../advanced_config/parameter_reference.html#CAL_GYRO0_PRIO">CAL_GYROn_PRIO</a>, <a href="./../advanced_config/parameter_reference.html#CAL_ACC0_PRIO">CAL_ACCn_PRIO</a>, <a href="./../advanced_config/parameter_reference.html#CAL_BARO0_PRIO">CAL_BAROn_PRIO</a>, <a href="./../advanced_config/parameter_reference.html#CAL_MAG0_PRIO">CAL_MAGn_PRIO</a>, where <code>n</code> is the instance number of the IMU component (0, 1, etc.).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>In most cases the external IMU is the highest-numbered. Ви можете отримати список доступних компонентів IMU, використовуючи <a href="./../middleware/uorb.html#uorb-top-command"><code>uorb top -1</code></a>, ви можете відрізняти їх за допомогою команди <a href="./../modules/modules_command.html#listener"><code>listener</code></a> та розглядаючи дані чи просто швидкості.</p></div></li></ul></li></ol><p>:::</p><ol start="5"><li>Перезавантажте PX4.</li></ol><p>Після активації модуль буде виявлено при завантаженні.</p><h2 id="inertial-labs-sensor-configuration" tabindex="-1">Inertial Labs Sensor Configuration <a class="header-anchor" href="#inertial-labs-sensor-configuration" aria-label="Permalink to &quot;Inertial Labs Sensor Configuration&quot;">​</a></h2><p>Perform sensor configuration according to the Interface Control Document (ICD) that comes with each device. The sensor-configuration software allows you to set the baurate and the data format, and you can also adjust the orientation axes if the sensor wasn&#39;t oriented in the normal way. This process is usually short and takes a few minutes, depending on the sensor and the installation conditions on the vehicle.</p><h2 id="опубліковані-дані" tabindex="-1">Опубліковані дані <a class="header-anchor" href="#опубліковані-дані" aria-label="Permalink to &quot;Опубліковані дані&quot;">​</a></h2><p>These uORB topics are published:</p><ul><li><a href="./../msg_docs/SensorAccel.html">sensor_accel</a></li><li><a href="./../msg_docs/SensorGyro.html">датчик_гіроскопа</a></li><li><a href="./../msg_docs/SensorMag.html">sensor_mag</a></li><li><a href="./../msg_docs/SensorBaro.html">sensor_baro</a></li><li><a href="./../msg_docs/SensorGps.html">sensor_gps</a></li></ul><p>If enabled as an external INS, publishes:</p><ul><li><a href="./../msg_docs/VehicleLocalPosition.html">vehicle_local_position</a></li><li><a href="./../msg_docs/VehicleGlobalPosition.html">vehicle_global_positon</a></li><li><a href="./../msg_docs/VehicleAttitude.html">vehicle_attitude</a></li></ul><p>If enabled as external sensor only:</p><ul><li><code>external_ins_local_position</code></li><li><code>external_ins_global_position</code></li><li><code>external_ins_attitude</code></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Опубліковані теми можна переглянути за допомогою команди <code>listener</code>.</p></div>',31)]))}const _=r(n,[["render",s]]);export{m as __pageData,_ as default};
